  1	import { Component, DestroyRef, ElementRef, Injector, afterNextRender, computed, inject, signal, viewChild } from '@angular/core';
  2	import { Title } from '@angular/platform-browser';
  3	import { ActivatedRoute, Router } from '@angular/router';
  4	import type { Subscription } from 'rxjs';
  5	import { CLOCK } from '../../core/clock';
  6	import { CountryStore } from '../../core/country-store';
  7	import { FormFieldStore } from '../../core/form-field-store';
  8	import { PaymentGateway, PaymentInProgressError } from '../../core/payment-gateway';
  9	import { PlanStore } from '../../core/plan-store';
 10	import { QuoteStore } from '../../core/quote-store';
 11	import { RANDOM_DIGITS } from '../../core/random-digits';
 12	import { TermsApi } from '../../core/terms-api';
 13	import type { Country } from '../../shared/country.model';
 14	import { LoadError } from '../../shared/load-error';
 15	import { formatMoney } from '../../shared/money-format';
 16	import type { Plan } from '../../shared/plan.model';
 17	import { calculateFinalPrice } from '../../shared/price-rules';
 18	import { formatQuoteNumber } from '../../shared/quote-number';
 19	import { RichText } from '../../shared/rich-text';
 20	import { buildSummaryRows, type SummaryRows } from '../../shared/summary-rows';
 21	import type { Terms } from '../../shared/terms.model';
 22	
 23	type DataStatus = 'loading' | 'error' | 'ready';
 24	type TermsStatus = 'loading' | 'error' | 'none' | 'shown';
 25	type PaymentState = 'idle' | 'processing' | 'rejected' | 'confirmed';
 26	
 27	const APP_TITLE = 'Cotizador de seguro de auto';
 28	const SUMMARY_HEADING = 'Resumen de tu cotización';
 29	const CONFIRMED_HEADING = 'Pago confirmado';
 30	
 31	/** The chosen plan with its final price, formatted for the country (US-03-BR-01). */
 32	interface ChosenPlanView {
 33	  plan: Plan;
 34	  price: string;
 35	}
 36	
 37	/**
 38	 * Step 3 (`/:country/resumen`): the summary, the terms, the simulated payment and the
 39	 * confirmation, all on one address (US-03-Q-06). The data are re-derived from the wizard state
 40	 * and this page load's configuration; the terms are one extra read-only request (ADR-0009); the
 41	 * payment goes through the `PaymentGateway` boundary and sends nothing (ADR-0008).
 42	 */
 43	@Component({
 44	  selector: 'app-summary-page',
 45	  imports: [LoadError, RichText],
 46	  templateUrl: './summary-page.html',
 47	  styleUrl: './summary-page.css',
 48	})
 49	export class SummaryPage {
 50	  private readonly route = inject(ActivatedRoute);
 51	  private readonly router = inject(Router);
 52	  private readonly injector = inject(Injector);
 53	  private readonly title = inject(Title);
 54	  private readonly countries = inject(CountryStore);
 55	  private readonly fields = inject(FormFieldStore);
 56	  private readonly plans = inject(PlanStore);
 57	  private readonly quote = inject(QuoteStore);
 58	  private readonly termsApi = inject(TermsApi);
 59	  private readonly gateway = inject(PaymentGateway);
 60	  private readonly clock = inject(CLOCK);
 61	  private readonly randomDigits = inject(RANDOM_DIGITS);
 62	  private readonly abort = new AbortController();
 63	  private readonly heading = viewChild.required<ElementRef<HTMLHeadingElement>>('heading');
 64	  private readonly country: Country | undefined = this.countries.find(this.route.snapshot.paramMap.get('country') ?? '');
 65	  private termsRequest: Subscription | null = null;
 66	
 67	  protected readonly dataStatus = signal<DataStatus>('loading');
 68	  protected readonly rows = signal<SummaryRows>({ holder: [], vehicle: [] });
 69	  protected readonly chosen = signal<ChosenPlanView | null>(null);
 70	
 71	  protected readonly termsStatus = signal<TermsStatus>('loading');
 72	  protected readonly terms = signal<Terms | null>(null);
 73	  protected readonly accepted = signal(false);
 74	
 75	  protected readonly outcome = signal<'approved' | 'rejected'>('approved');
 76	  protected readonly paymentState = signal<PaymentState>('idle');
 77	  protected readonly quoteNumber = signal('');
 78	
 79	  protected readonly processing = computed(() => this.paymentState() === 'processing');
 80	  protected readonly confirmed = computed(() => this.paymentState() === 'confirmed');
 81	  protected readonly canPay = computed(() => this.termsStatus() === 'shown' && this.accepted() && ['idle', 'rejected'].includes(this.paymentState()));
 82	  /** The reason "Pagar" is unavailable, shown next to it and linked to it (US-03-BR-04). */
 83	  protected readonly showHint = computed(() => this.termsStatus() === 'shown' && !this.accepted());
 84	
 85	  constructor() {
 86	    inject(DestroyRef).onDestroy(() => {
 87	      // Leaving the page abandons any attempt: nothing is cleared and nothing is shown.
 88	      this.abort.abort();
 89	      this.termsRequest?.unsubscribe();
 90	    });
 91	    void this.load();
 92	    this.loadTerms();
 93	    // Arriving at the step puts focus on its heading. A terms failure is not caused by the person,
 94	    // so the focus stays there too.
 95	    afterNextRender(() => this.heading().nativeElement.focus());
 96	  }
 97	
 98	  protected async load(): Promise<void> {
 99	    const country = this.country;
100	    if (!country) {
101	      this.dataStatus.set('error');
102	      return;
103	    }
104	    this.dataStatus.set('loading');
105	    try {
106	      const [configs, offered] = await Promise.all([this.fields.load(country.code), this.plans.load(country.code)]);
107	      // The typed step 1 output is re-derived with this page load's configuration (US-02-Q-17);
108	      // the step guards checked that it is valid.
109	      const step1 = this.quote.completeStep1(configs);
110	      const plan = offered.find((p) => p.key === this.quote.plan()?.key);
111	      if (step1 === null || !plan) throw new Error('the summary has no valid step 1 or plan');
112	      this.rows.set(buildSummaryRows(configs, step1, country.locale));
113	      this.chosen.set({ plan, price: formatMoney(calculateFinalPrice(plan.basePrice, step1, this.clock()), country.locale, country.currencyCode) });
114	      this.dataStatus.set('ready');
115	    } catch {
116	      this.dataStatus.set('error');
117	    }
118	  }
119	
120	  /** One terms request per entry and per "Reintentar" (spec 7.2). */
121	  protected loadTerms(): void {
122	    const country = this.country;
123	    if (!country) {
124	      this.termsStatus.set('error');
125	      return;
126	    }
127	    this.termsRequest?.unsubscribe();
128	    this.termsStatus.set('loading');
129	    this.termsRequest = this.termsApi.load(country.code).subscribe({
130	      next: (terms) => {
131	        this.terms.set(terms);
132	        this.termsStatus.set(terms === null ? 'none' : 'shown');
133	      },
134	      error: () => this.termsStatus.set('error'),
135	    });
136	  }
137	
138	  protected accept(event: Event): void {
139	    this.accepted.set((event.target as HTMLInputElement).checked);
140	  }
141	
142	  protected chooseOutcome(value: 'approved' | 'rejected'): void {
143	    this.outcome.set(value);
144	  }
145	
146	  protected editData(): void {
147	    this.leaveTo('datos');
148	  }
149	
150	  protected changePlan(): void {
151	    this.leaveTo('planes');
152	  }
153	
154	  protected newQuote(): void {
155	    this.leaveTo('datos');
156	  }
157	
158	  /** Activation of "Pagar": exactly one attempt, locked synchronously before any await (US-03-BR-05). */
159	  protected async pay(): Promise<void> {
160	    if (!this.canPay() || !this.country) return;
161	    this.paymentState.set('processing');
162	    const country = this.country;
163	    try {
164	      const result = await this.gateway.pay({ simulatedOutcome: this.outcome() }, this.abort.signal);
165	      if (this.abort.signal.aborted) return;
166	      if (result.status === 'approved') {
167	        // Order of ADR-0008: number, then the state is deleted, then the confirmation.
168	        this.quoteNumber.set(formatQuoteNumber(country.code, this.clock(), this.randomDigits()));
169	        this.quote.clearQuote();
170	        this.paymentState.set('confirmed');
171	        this.title.setTitle(`${CONFIRMED_HEADING} | ${APP_TITLE}`);
172	        afterNextRender(() => this.heading().nativeElement.focus(), { injector: this.injector });
173	      } else {
174	        this.paymentState.set('rejected');
175	      }
176	    } catch (error) {
177	      if (this.abort.signal.aborted || error instanceof PaymentInProgressError) return;
178	      this.paymentState.set('rejected');
179	    }
180	  }
181	
182	  protected headingText(): string {
183	    return this.confirmed() ? CONFIRMED_HEADING : SUMMARY_HEADING;
184	  }
185	
186	  private leaveTo(step: 'datos' | 'planes'): void {
187	    if (this.processing()) return;
188	    void this.router.navigate(['/', (this.country?.code ?? '').toLowerCase(), step]);
189	  }
190	}
  1	<main class="page">
  2	  <h1 #heading tabindex="-1">{{ headingText() }}</h1>
  3	
  4	  @if (confirmed()) {
  5	    <section class="confirmation">
  6	      <p class="confirmation__number">
  7	        Tu número de cotización es
  8	        <strong class="confirmation__code">{{ quoteNumber() }}</strong>
  9	      </p>
 10	      <p class="confirmation__notice">Este es un pago simulado; no se realizó ningún cobro real.</p>
 11	      <div class="actions">
 12	        <button type="button" (click)="newQuote()">Nueva cotización</button>
 13	      </div>
 14	    </section>
 15	  } @else {
 16	    @switch (dataStatus()) {
 17	      @case ('loading') {
 18	        <p role="status">Cargando resumen…</p>
 19	      }
 20	      @case ('error') {
 21	        <app-load-error message="No pudimos cargar el resumen. Intenta de nuevo." (retry)="load()" />
 22	      }
 23	      @case ('ready') {
 24	        <div class="summary" [attr.aria-busy]="processing() ? 'true' : null">
 25	          @if (rows().holder.length > 0) {
 26	            <section class="card" aria-labelledby="holder-heading">
 27	              <h2 id="holder-heading">Tus datos</h2>
 28	              <dl class="rows">
 29	                @for (row of rows().holder; track row.key) {
 30	                  <div class="row">
 31	                    <dt>{{ row.label }}</dt>
 32	                    @if (row.accessibleValue) {
 33	                      <dd>
 34	                        <span aria-hidden="true">{{ row.value }}</span>
 35	                        <span class="visually-hidden">{{ row.accessibleValue }}</span>
 36	                      </dd>
 37	                    } @else {
 38	                      <dd>{{ row.value }}</dd>
 39	                    }
 40	                  </div>
 41	                }
 42	              </dl>
 43	            </section>
 44	          }
 45	          @if (rows().vehicle.length > 0) {
 46	            <section class="card" aria-labelledby="vehicle-heading">
 47	              <h2 id="vehicle-heading">Tu vehículo</h2>
 48	              <dl class="rows">
 49	                @for (row of rows().vehicle; track row.key) {
 50	                  <div class="row">
 51	                    <dt>{{ row.label }}</dt>
 52	                    <dd>{{ row.value }}</dd>
 53	                  </div>
 54	                }
 55	              </dl>
 56	            </section>
 57	          }
 58	          <div class="actions">
 59	            <button type="button" class="secondary" [attr.aria-disabled]="processing() ? 'true' : null" (click)="editData()">Editar mis datos</button>
 60	          </div>
 61	
 62	          @if (chosen(); as item) {
 63	            <section class="card" aria-labelledby="plan-heading">
 64	              <h2 id="plan-heading">Plan elegido</h2>
 65	              <p class="plan__name">{{ item.plan.name }}</p>
 66	              <p class="plan__description">{{ item.plan.shortDescription }}</p>
 67	              <p class="plan__price">
 68	                <span class="plan__amount">{{ item.price }}</span>
 69	                <span class="plan__caption">Precio anual</span>
 70	              </p>
 71	              <div class="actions">
 72	                <button type="button" class="secondary" [attr.aria-disabled]="processing() ? 'true' : null" (click)="changePlan()">Cambiar plan</button>
 73	              </div>
 74	            </section>
 75	          }
 76	
 77	          <section class="card" aria-labelledby="terms-heading" [attr.aria-busy]="termsStatus() === 'loading' ? 'true' : null">
 78	            <h2 id="terms-heading">Términos y condiciones</h2>
 79	            @switch (termsStatus()) {
 80	              @case ('loading') {
 81	                <p role="status">Cargando términos y condiciones…</p>
 82	              }
 83	              @case ('error') {
 84	                <p role="alert" class="message--error">No pudimos cargar los términos y condiciones. Intenta de nuevo.</p>
 85	                <button type="button" (click)="loadTerms()">Reintentar</button>
 86	              }
 87	              @case ('none') {
 88	                <p role="status">Los términos y condiciones no están disponibles en este momento. No es posible pagar.</p>
 89	              }
 90	              @case ('shown') {
 91	                @if (terms(); as shown) {
 92	                  <div class="terms" role="region" tabindex="0" aria-labelledby="terms-title">
 93	                    <h3 id="terms-title">{{ shown.title }}</h3>
 94	                    <app-rich-text [blocks]="shown.blocks" [headingLevel]="4" />
 95	                  </div>
 96	                }
 97	              }
 98	            }
 99	          </section>
100	        </div>
101	
102	        <div class="payment">
103	          @if (termsStatus() === 'shown') {
104	            <div class="accept">
105	              <input id="accept-terms" type="checkbox" [checked]="accepted()" [disabled]="processing()" (change)="accept($event)" />
106	              <label for="accept-terms">Acepto los términos y condiciones</label>
107	            </div>
108	          }
109	          <fieldset class="simulation" [disabled]="processing()">
110	            <legend>Simulación de pago (no se realiza ningún cobro)</legend>
111	            <label class="choice">
112	              <input type="radio" name="simulation" value="approved" [checked]="outcome() === 'approved'" (change)="chooseOutcome('approved')" />
113	              Pago aprobado
114	            </label>
115	            <label class="choice">
116	              <input type="radio" name="simulation" value="rejected" [checked]="outcome() === 'rejected'" (change)="chooseOutcome('rejected')" />
117	              Pago rechazado
118	            </label>
119	          </fieldset>
120	          @if (showHint()) {
121	            <p id="pay-hint" class="hint">Acepta los términos y condiciones para pagar.</p>
122	          }
123	          <div class="actions">
124	            <button type="button" class="pay" [attr.aria-disabled]="canPay() ? null : 'true'" [attr.aria-describedby]="showHint() ? 'pay-hint' : null" (click)="pay()">
125	              {{ processing() ? 'Procesando pago…' : 'Pagar' }}
126	            </button>
127	          </div>
128	          @if (paymentState() === 'rejected') {
129	            <p role="alert" class="message--error">El pago fue rechazado y no se realizó ningún cobro. Puedes intentarlo de nuevo.</p>
130	          }
131	        </div>
132	      }
133	    }
134	  }
135	  <div role="status" class="visually-hidden">{{ processing() ? 'Procesando pago…' : '' }}</div>
136	</main>

