10	 * The boundary a real payment provider would replace (ADR-0008). Also the DI token. `pay` rejects
11	 * with an `AbortError` when the signal is aborted, and with `PaymentInProgressError` when an
12	 * attempt is already in flight.
13	 */
14	export abstract class PaymentGateway {
15	  abstract pay(request: PaymentRequest, signal: AbortSignal): Promise<PaymentResult>;
16	}
17	
18	/** A second `pay` was called while an attempt was still in flight. */
19	export class PaymentInProgressError extends Error {
20	  constructor() {
21	    super('A payment attempt is already in progress');
