 4	/** The fixed time a simulated payment takes (US-03-AC-15). */
 5	export const SIMULATED_PROCESSING_MS = 1500;
 6	
 7	type Delay = (ms: number, signal: AbortSignal) => Promise<void>;
 8	
 9	const abortError = (): DOMException => new DOMException('The payment was aborted', 'AbortError');
10	
11	/** Timer based, never a loop on `Date.now()`: the e2e tests pin the page clock. Cleared on abort. */
12	const timerDelay: Delay = (ms, signal) =>
13	  new Promise<void>((resolve, reject) => {
14	    if (signal.aborted) {
15	      reject(abortError());
16	      return;
17	    }
18	    const onAbort = (): void => {
19	      clearTimeout(timer);
20	      reject(abortError());
21	    };
22	    const timer = setTimeout(() => {
23	      signal.removeEventListener('abort', onAbort);
24	      resolve();
25	    }, ms);
26	    signal.addEventListener('abort', onAbort, { once: true });
27	  });
28	
29	/** The wait of the simulation, injectable so tests control time. */
30	export const PAYMENT_DELAY = new InjectionToken<Delay>('PAYMENT_DELAY', { providedIn: 'root', factory: () => timerDelay });
31	
32	/**
33	 * The simulated gateway (ADR-0008): waits a fixed time, then answers the outcome it was asked for.
34	 * No HTTP, no storage and no payment data. One attempt at a time.
35	 */
36	@Injectable()
37	export class SimulatedPaymentGateway extends PaymentGateway {
38	  private readonly delay = inject(PAYMENT_DELAY);
39	  private inFlight = false;
40	
41	  async pay(request: PaymentRequest, signal: AbortSignal): Promise<PaymentResult> {
42	    if (this.inFlight) throw new PaymentInProgressError();
43	    if (signal.aborted) throw abortError();
44	    this.inFlight = true;
45	    try {
46	      await this.delay(SIMULATED_PROCESSING_MS, signal);
47	      return { status: request.simulatedOutcome };
48	    } finally {
49	      this.inFlight = false;
50	    }
51	  }
52	}
