 1	const BULLET = '•';
 2	const ALNUM = /[\p{L}\p{N}]/u;
 3	const MAX_VISIBLE = 4;
 4	
 5	export interface MaskedDocument {
 6	  /** The value with every hidden letter or digit replaced by a bullet. */
 7	  text: string;
 8	  /** What a screen reader gets instead of the masked string. */
 9	  accessibleText: string;
10	}
11	
12	/**
13	 * Partial masking of the document number (US-03-BR-02): with n letters and digits, the last
14	 * k = min(4, floor(n / 2)) stay visible; every earlier one becomes a bullet; separators stay in
15	 * place. One rule for every country, no country branch.
16	 */
17	export function maskDocumentNumber(value: string): MaskedDocument {
18	  const chars = Array.from(value);
19	  const total = chars.filter((c) => ALNUM.test(c)).length;
20	  const visible = Math.min(MAX_VISIBLE, Math.floor(total / 2));
21	  const hiddenCount = total - visible;
22	  let seen = 0;
23	  let firstVisible = chars.length;
24	  const masked = chars.map((c, index) => {
25	    if (!ALNUM.test(c)) return c;
26	    seen++;
27	    if (seen <= hiddenCount) return BULLET;
28	    if (firstVisible === chars.length) firstVisible = index;
29	    return c;
30	  });
31	  const tail = visible > 0 ? chars.slice(firstVisible).join('') : '';
32	  return {
33	    text: masked.join(''),
34	    accessibleText: tail === '' ? 'Número oculto' : `Número oculto, termina en ${tail}`,
35	  };
36	}
