  9	const MAX_LIST_DEPTH = 6;
 10	const SHORT_IDENTIFIER = /^[a-z-]{1,32}$/;
 11	
 12	type Wire = Record<string, unknown>;
 13	const isRec = (v: unknown): v is Wire => typeof v === 'object' && v !== null && !Array.isArray(v);
 14	const isBlank = (spans: readonly RichTextSpan[]): boolean => spans.every((s) => s.text.trim() === '');
 15	
 16	/** The node type for a warning: a short identifier as is, anything else "unknown" (it may be markup). */
 17	function typeName(node: unknown): string {
 18	  const type = isRec(node) ? node['type'] : undefined;
 19	  return typeof type === 'string' && SHORT_IDENTIFIER.test(type) ? type : 'unknown';
 20	}
 21	
 22	function warn(what: string): void {
 23	  console.warn(`rich text: ${what}`);
 24	}
 25	
 26	/** The spans of the inline children of a block; links keep their text only. */
 27	function parseInline(children: unknown[]): RichTextSpan[] {
 28	  const spans: RichTextSpan[] = [];
 29	  for (const child of children) {
 30	    if (isRec(child) && child['type'] === 'text') {
 31	      if (typeof child['text'] !== 'string') {
 32	        warn('text');
 33	        continue;
 34	      }
 35	      spans.push({
 36	        text: child['text'],
 37	        bold: child['bold'] === true,
 38	        italic: child['italic'] === true,
 39	        underline: child['underline'] === true,
 40	        strikethrough: child['strikethrough'] === true,
 41	      });
 42	    } else if (isRec(child) && child['type'] === 'link') {
 43	      warn('link');
 44	      if (Array.isArray(child['children'])) spans.push(...parseInline(child['children']));
 45	    } else {
 46	      warn(typeName(child));
 47	    }
 48	  }
 49	  return spans;
 50	}
 51	
 52	function parseList(node: Wire, depth: number): RichTextList | null {
 53	  const format = node['format'];
 54	  if ((format !== 'ordered' && format !== 'unordered') || !Array.isArray(node['children'])) {
 55	    warn('list');
 56	    return null;
 57	  }
 58	  const items: RichTextListItem[] = [];
 59	  // The item a following nested list attaches to; null when none, or the item was dropped.
 60	  let last: RichTextListItem | null = null;
 61	  for (const child of node['children']) {
 62	    if (isRec(child) && child['type'] === 'list') {
 63	      if (depth >= MAX_LIST_DEPTH) {
 64	        warn('list-depth');
 65	        continue;
 66	      }
 67	      const nested = parseList(child, depth + 1);
 68	      if (!nested) continue;
 69	      if (!last) {
 70	        last = { spans: [], lists: [] };
 71	        items.push(last);
 72	      }
 73	      last.lists.push(nested);
 74	    } else if (isRec(child) && child['type'] === 'list-item' && Array.isArray(child['children'])) {
 75	      const spans = parseInline(child['children']);
 76	      if (isBlank(spans)) {
 77	        last = null;
 78	        continue;
 79	      }
 80	      last = { spans, lists: [] };
 81	      items.push(last);
 82	    } else {
 83	      warn(typeName(child));
 84	    }
 85	  }
 86	  return items.length > 0 ? { ordered: format === 'ordered', items } : null;
 87	}
