 94	/** `null` when the whole body is malformed: not an array, or no text left after the rules. */
 95	export function parseRichTextBlocks(value: unknown): RichTextBlock[] | null {
 96	  if (!Array.isArray(value)) {
 97	    warn('body');
 98	    return null;
 99	  }
100	  // Headings are collected with their level; depth is relative to the smallest level kept.
101	  const pending: (RichTextBlock | RawHeading)[] = [];
102	  for (const node of value) {
103	    if (!isRec(node)) {
104	      warn(typeName(node));
105	      continue;
106	    }
107	    const type = node['type'];
108	    const children = node['children'];
109	    if (type === 'list') {
110	      const list = parseList(node, 1);
111	      if (list) pending.push({ kind: 'list', list });
112	    } else if (type === 'paragraph' || type === 'quote' || type === 'code' || type === 'heading') {
113	      if (!Array.isArray(children)) {
114	        warn(typeName(node));
115	        continue;
116	      }
117	      const level = node['level'];
118	      if (type === 'heading' && !(typeof level === 'number' && Number.isInteger(level) && level >= 1 && level <= 6)) {
119	        warn('heading');
120	        continue;
121	      }
122	      if (type === 'quote' || type === 'code') warn(type);
123	      const spans = parseInline(children);
124	      if (isBlank(spans)) continue;
125	      pending.push(type === 'heading' ? { level: level as number, spans } : { kind: 'paragraph', spans });
126	    } else {
127	      warn(typeName(node));
128	    }
129	  }
130	  const levels = pending.filter((b): b is RawHeading => 'level' in b).map((h) => h.level);
131	  const smallest = levels.length > 0 ? Math.min(...levels) : 1;
132	  const blocks: RichTextBlock[] = pending.map((b) => ('level' in b ? { kind: 'heading', depth: b.level - smallest, spans: b.spans } : b));
133	  if (blocks.length === 0) {
134	    warn('body');
135	    return null;
136	  }
137	  return blocks;
138	}
