 48	 */
 49	export function buildSummaryRows(configs: readonly FieldConfig[], output: Step1Output, locale: string): SummaryRows {
 50	  const rows: SummaryRows = { holder: [], vehicle: [] };
 51	  const ordered = [...configs].sort((a, b) => a.sortOrder - b.sortOrder || a.key.localeCompare(b.key));
 52	  for (const config of ordered) {
 53	    if (config.type === 'checkbox') continue;
 54	    const value = output.values[config.key];
 55	    if (value === undefined || value === null || value === '') continue;
