  1	import { maskDocumentNumber } from './document-mask';
  2	import type { FieldConfig, OutputValue, Step1Output } from './field-config.model';
  3	import { parseIsoDate } from './field-validators';
  4	
  5	export interface SummaryRow {
  6	  key: string;
  7	  label: string;
  8	  value: string;
  9	  /** The text a screen reader gets instead of `value` (only the masked document number). */
 10	  accessibleValue?: string;
 11	}
 12	
 13	export interface SummaryRows {
 14	  holder: SummaryRow[];
 15	  vehicle: SummaryRow[];
 16	}
 17	
 18	/** The reserved step 1 keys that describe the vehicle (US-01-Q-08); every other key is the holder's. */
 19	const VEHICLE_KEYS: readonly string[] = ['plate', 'make', 'model', 'vehicleYear'];
 20	const DOCUMENT_KEY = 'documentNumber';
 21	
 22	function longDate(text: string, locale: string): string {
 23	  const parts = parseIsoDate(text);
 24	  if (!parts) return text;
 25	  const date = new Date(Date.UTC(parts.year, parts.month - 1, parts.day));
 26	  try {
 27	    return new Intl.DateTimeFormat(locale, { dateStyle: 'long', timeZone: 'UTC' }).format(date);
 28	  } catch {
 29	    return text;
 30	  }
 31	}
 32	
 33	function displayValue(config: FieldConfig, value: OutputValue, locale: string): string {
 34	  switch (config.type) {
 35	    case 'select':
 36	      return config.options?.find((o) => o.value === String(value))?.label ?? String(value);
 37	    case 'date':
 38	      return longDate(String(value), locale);
 39	    default:
 40	      return String(value);
 41	  }
 42	}
 43	
 44	/**
 45	 * The summary rows (US-03-BR-01): one per configured field with a non-empty value, except
 46	 * checkboxes, in sortOrder, split into the holder and the vehicle group. Labels come from this
 47	 * page load's configuration, never from the stored state.
 48	 */
 49	export function buildSummaryRows(configs: readonly FieldConfig[], output: Step1Output, locale: string): SummaryRows {
 50	  const rows: SummaryRows = { holder: [], vehicle: [] };
 51	  const ordered = [...configs].sort((a, b) => a.sortOrder - b.sortOrder || a.key.localeCompare(b.key));
 52	  for (const config of ordered) {
 53	    if (config.type === 'checkbox') continue;
 54	    const value = output.values[config.key];
 55	    if (value === undefined || value === null || value === '') continue;
 56	    const row: SummaryRow = { key: config.key, label: config.label, value: displayValue(config, value, locale) };
 57	    if (config.key === DOCUMENT_KEY) {
 58	      const masked = maskDocumentNumber(String(value));
 59	      row.value = masked.text;
 60	      row.accessibleValue = masked.accessibleText;
 61	    }
 62	    (VEHICLE_KEYS.includes(config.key) ? rows.vehicle : rows.holder).push(row);
 63	  }
 64	  return rows;
 65	}

