content.content:
services:
  strapi:
    build:
      context: ./backend
    ports:
      # Localhost only: the dev admin password is public in the repo (US-01-R1-F07). The browser
      # reaches the content API through `web`; the host (e2e tests, admin panel) uses this port.
      # IPv4 loopback is enough: browsers and Node 24 (autoSelectFamily) fall back from ::1 to
      # 127.0.0.1 for `localhost`. An earlier extra [::1] binding rested on a misdiagnosis (FLOW.md).
      - "127.0.0.1:1337:1337"
    environment:
      HOST: 0.0.0.0
      PORT: 1337
      # Empty values make the entrypoint generate dev-only secrets (kept in the volume).
      APP_KEYS: ${APP_KEYS:-}
      ADMIN_JWT_SECRET: ${ADMIN_JWT_SECRET:-}
      API_TOKEN_SALT: ${API_TOKEN_SALT:-}
      TRANSFER_TOKEN_SALT: ${TRANSFER_TOKEN_SALT:-}
      ENCRYPTION_KEY: ${ENCRYPTION_KEY:-}
      JWT_SECRET: ${JWT_SECRET:-}
      # Development super admin, created on first start when no admin exists (ADR-0002).
      # Clearly fictitious, dev-only defaults so that one command works; override them in .env.
      STRAPI_ADMIN_EMAIL: ${STRAPI_ADMIN_EMAIL:-dev.admin@example.com}
      STRAPI_ADMIN_PASSWORD: ${STRAPI_ADMIN_PASSWORD:-DevOnly-Passw0rd}
      # CORS allow-list (comma-separated origins). Empty: the browser uses the same-origin proxy.
      CORS_ORIGINS: ${CORS_ORIGINS:-}
    volumes:
      - strapi-data:/data
    healthcheck:
      test: ["CMD", "node", "-e", "fetch('http://127.0.0.1:1337/_health').then(r=>process.exit(r.status===204?0:1)).catch(()=>process.exit(1))"]
      interval: 10s
      timeout: 5s
      retries: 12
      start_period: 30s

  # nginx serving the Angular build and proxying /api to Strapi (ADR-0002). The image is built
  # from ./frontend; the upstream address is applied at container start by the nginx template.
  web:
    build: ./frontend
    ports:
      - "8080:80"
    environment:
      STRAPI_UPSTREAM: http://strapi:1337
    depends_on:
      strapi:
        condition: service_healthy

volumes:
  strapi-data:
# Same-origin proxy and static host of the Angular build (ADR-0002).
# Processed by the nginx image's envsubst at container start: only ${STRAPI_UPSTREAM} is
# substituted, nginx variables ($uri, $request_method, ...) are untouched.

server {
    listen 80;
    server_name _;
    server_tokens off;

    root /usr/share/nginx/html;
    index index.html;

    gzip on;
    gzip_types text/css application/javascript application/json image/svg+xml;

    # --- Content API: read-only, allow-listed, never cached ---------------------------------

    # Allow-list (US-01): the published countries and form fields; US-02 adds the plans, US-03 the terms.
    location ~ ^/api/(countries|form-fields|plans|terms)/?$ {
        # Only GET (and the implicit HEAD) reaches Strapi.
        if ($request_method !~ ^(GET|HEAD)$) {
            add_header Cache-Control "no-store" always;
            add_header Allow "GET, HEAD" always;
            return 405;
        }
        # The proxy can never be used to replay a token from a browser.
        if ($http_authorization != "") {
            add_header Cache-Control "no-store" always;
            return 400;
        }

        proxy_pass ${STRAPI_UPSTREAM};
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Authorization "";
        proxy_read_timeout 15s;
        proxy_cache off;
        # Business content must be fresh (US-01-BR-06): one Cache-Control, ours.
        proxy_hide_header Cache-Control;
        proxy_hide_header Expires;
        proxy_hide_header ETag;
        proxy_hide_header Last-Modified;
        add_header Cache-Control "no-store" always;
    }

    # Any other path under /api/ is answered here and never reaches Strapi.
    location /api/ {
        add_header Cache-Control "no-store" always;
        return 404;
    }

    # --- Angular build -----------------------------------------------------------------------

    # The entry point is revalidated on every load; it names the hashed bundles.
    location = /index.html {
        add_header Cache-Control "no-cache";
    }

    # Hashed bundles may be cached for a long time: their names change on every build.
    location ~* \.(?:js|css)$ {
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable";
    }

    # Client-side routes (/, /co/datos, ...) fall back to index.html.
    location / {
        try_files $uri /index.html;
    }
}

