import { Component, ElementRef, afterNextRender, input, output, viewChild } from '@angular/core';

/**
 * Error state of a remote load: the message in a `role="alert"` region and a "Reintentar" button
 * that takes focus when the state appears (spec section 8).
 */
@Component({
  selector: 'app-load-error',
  template: `
    <p role="alert" class="load-error__message">{{ message() }}</p>
    <button type="button" #retryButton (click)="retry.emit()">Reintentar</button>
  `,
  styles: `
    :host {
      display: block;
    }
    .load-error__message {
      margin: 0 0 1rem;
      color: var(--color-error);
      font-weight: 600;
    }
  `,
})
export class LoadError {
  readonly message = input.required<string>();
  readonly retry = output<void>();
  private readonly retryButton = viewChild.required<ElementRef<HTMLButtonElement>>('retryButton');

  constructor() {
    afterNextRender(() => this.retryButton().nativeElement.focus());
  }
}
:host {
  display: block;
}
.page {
  max-width: 48rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 3rem;
}
h1 {
  margin: 0 0 1rem;
  font-size: 1.5rem;
  line-height: 1.3;
}
h1:focus:not(:focus-visible) {
  outline: none;
}
h2 {
  margin: 0 0 0.75rem;
  font-size: 1.25rem;
  line-height: 1.3;
}
.summary {
  display: grid;
  gap: 1rem;
}
.card {
  padding: 1rem;
  border: 2px solid var(--color-border);
  border-radius: 0.75rem;
  background: var(--color-surface);
}
/* One column on narrow screens: the label above its value. Side by side from 40rem. */
.rows {
  display: grid;
  gap: 0.75rem;
  margin: 0;
}
.row {
  display: grid;
  gap: 0.125rem;
}
dt {
  color: var(--color-muted);
  font-size: 0.875rem;
}
dd {
  margin: 0;
  font-weight: 600;
  overflow-wrap: anywhere;
}
@media (min-width: 40rem) {
  .row {
    grid-template-columns: 12rem 1fr;
    gap: 1rem;
  }
}
.plan__name {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 700;
}
.plan__description {
  margin: 0.5rem 0 0;
  color: var(--color-muted);
}
.plan__price {
  margin: 0.75rem 0 0;
}
.plan__amount {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
  overflow-wrap: anywhere;
}
.plan__caption {
  color: var(--color-muted);
  font-size: 0.875rem;
}
/* The terms scroll inside their own box, so the page and the pay button stay in reach. */
.terms {
  max-height: min(24rem, 60vh);
  padding: 0.75rem 1rem;
  overflow-y: auto;
  border: 1px solid var(--color-border-strong);
  border-radius: 0.5rem;
}
.terms h3 {
  margin: 0 0 0.75rem;
  font-size: 1.125rem;
  line-height: 1.3;
}
.payment {
  display: grid;
  gap: 1rem;
  margin-top: 1.5rem;
}
.accept {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}
.accept input,
.choice input {
  flex: none;
  width: 1.5rem;
  height: 1.5rem;
  margin: 0;
}
.accept label {
  padding-block: 0.125rem;
}
.simulation {
  display: grid;
  gap: 0.5rem;
  margin: 0;
  padding: 0.75rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
}
.simulation legend {
  padding-inline: 0.25rem;
  font-weight: 600;
}
.choice {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 2.75rem;
}
.hint {
  margin: 0;
  color: var(--color-muted);
}
.message--error {
  margin: 0;
  color: var(--color-error);
  font-weight: 600;
}
.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.secondary {
  border: 2px solid var(--color-button);
  background: var(--color-surface);
  color: var(--color-button);
}
button[aria-disabled='true'] {
  background: var(--color-border);
  border-color: var(--color-border-strong);
  color: var(--color-muted);
  cursor: not-allowed;
}
button[aria-disabled='true']:hover {
  filter: none;
}
.pay {
  width: 100%;
}
@media (min-width: 40rem) {
  .pay {
    width: auto;
    min-width: 12rem;
  }
}
.confirmation {
  display: grid;
  gap: 1rem;
}
.confirmation p {
  margin: 0;
}
.confirmation__code {
  display: block;
  font-size: 1.5rem;
  overflow-wrap: anywhere;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

