  align-items: center;
  gap: 0.75rem;
  min-height: 2.75rem;
}
.hint {
  margin: 0;
  color: var(--color-muted);
}
.message--error {
  margin: 0;
  color: var(--color-error);
  font-weight: 600;
}
.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.secondary {
  border: 2px solid var(--color-button);
  background: var(--color-surface);
  color: var(--color-button);
}
button[aria-disabled='true'] {
  background: var(--color-border);
  border-color: var(--color-border-strong);
  color: var(--color-muted);
  cursor: not-allowed;
}
button[aria-disabled='true']:hover {
  filter: none;
}
.pay {
  width: 100%;
}
@media (min-width: 40rem) {
  .pay {
    width: auto;
    min-width: 12rem;
  }
}
.confirmation {
  display: grid;
  gap: 1rem;
}
.confirmation p {
  margin: 0;
}
.confirmation__code {
  display: block;
  font-size: 1.5rem;
  overflow-wrap: anywhere;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

